import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int n;
    static long[] bitC;
    static long[] bitK;

    static void add(long[] bit, int idx, long val) {
        for (int i = idx; i <= n; i += i & -i) {
            bit[i] += val;
        }
    }

    static long sum(long[] bit, int idx) {
        long res = 0;
        for (int i = idx; i > 0; i -= i & -i) {
            res += bit[i];
        }
        return res;
    }

    static void rangeAddConst(int l, int r, long val) {
        add(bitC, l, val);
        if (r + 1 <= n) add(bitC, r + 1, -val);
    }

    static void rangeAddCoeff(int l, int r, long val) {
        add(bitK, l, val);
        if (r + 1 <= n) add(bitK, r + 1, -val);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        n = fs.nextInt();
        int m = fs.nextInt();

        bitC = new long[n + 2];
        bitK = new long[n + 2];

        StringBuilder out = new StringBuilder();

        for (int q = 0; q < m; q++) {
            int type = fs.nextInt();

            if (type == 1) {
                int i = fs.nextInt();
                int v = fs.nextInt();

                int l = i;
                int r = Math.min(n, i + v - 1);

                long c = (long) v + i;
                long k = -1;

                rangeAddConst(l, r, c);
                rangeAddCoeff(l, r, k);
            } else if (type == 2) {
                int i = fs.nextInt();
                int v = fs.nextInt();

                int l = Math.max(1, i - v + 1);
                int r = i;

                long c = (long) v - i;
                long k = 1;

                rangeAddConst(l, r, c);
                rangeAddCoeff(l, r, k);
            } else {
                int i = fs.nextInt();

                long ans = sum(bitC, i) + sum(bitK, i) * i;
                out.append(ans).append('\n');
            }
        }

        System.out.print(out);
    }
}
